function initBarChart(n,t,i,r,u){let f=new Chart($(n),{type:"bar",data:{labels:[],datasets:[{label:i,data:[],backgroundColor:"rgba(76, 175, 80, 0.5)",borderColor:"#6da252",borderWidth:1}]},options:{animation:{duration:2e3,easing:"easeOutQuart"},plugins:{legend:{display:!1,position:"top"},title:{display:!0,text:r,position:"left"}}}});return f.ajax={reload:function(){showLoader(u);f.data.labels=[];f.data.datasets[0].data=[];f.update();$.ajax({url:t,type:"GET",success:function(n){f.data.labels=n.labels;f.data.datasets[0].data=n.datasets;f.update()},error:function(n){hideLoader(u);handleErrorApiResponse(n)},complete:function(){hideLoader(u)}})}},f}function initLineChart(n,t,i,r,u){let f=new Chart($(n),{type:"line",data:{labels:[],datasets:[{label:i,data:[],backgroundColor:"rgba(48, 164, 255, 0.2)",borderColor:"rgba(48, 164, 255, 0.8)",fill:!0,borderWidth:1}]},options:{animation:{duration:2e3,easing:"easeOutQuart"},plugins:{legend:{display:!1,position:"right"},title:{display:!0,text:r,position:"left"}}}});return f.ajax={reload:function(){showLoader(u);f.data.labels=[];f.data.datasets[0].data=[];f.update();$.ajax({url:t,type:"GET",success:function(n){f.data.labels=n.labels;f.data.datasets[0].data=n.datasets;f.update()},error:function(n){hideLoader(u);handleErrorApiResponse(n)},complete:function(){hideLoader(u)}})}},f}